static int uniphier_spi_transfer_one_irq ( struct spi_master * master , struct spi_device * spi , struct spi_transfer * t ) { struct uniphier_spi_priv * priv = spi_master_get_devdata ( master ) ; struct device * dev = master -> dev . parent ; reinit_completion ( & priv -> xfer_done ) ; uniphier_spi_fill_tx_fifo ( priv ) ; uniphier_spi_irq_enable ( priv , SSI_IE_RCIE | SSI_IE_RORIE ) ; time_left = wait_for_completion_timeout ( & priv -> xfer_done , msecs_to_jiffies ( SSI_TIMEOUT_MS ) ) ; uniphier_spi_irq_disable ( priv , SSI_IE_RCIE | SSI_IE_RORIE ) ; if ( ! time_left ) { dev_err ( dev , "transfer timeout.\n" ) ; return - ETIMEDOUT ; } return priv -> error ; } 